    /// The caller's own skill, or a shared one where the caller manages that level's skills. An edit of a shared skill by somebody who may not approve there sends it back for approval; switching a shared skill on or off is POST /api/ai/skills/{skillId}/approve.
    /// <para/>
    /// <c>PATCH /api/ai/skills/{skillId}</c>
    /// </remarks>
    /// <param name="skillId">The skill's id.</param>
    /// <param name="body">The body.</param>
    /// <param name="options">Per-call timeout, retries and headers.</param>
    /// <param name="cancellationToken">Cancels the call.</param>
    /// <returns>The answer's <c>data</c>.</returns>
    /// <exception cref="CrafvyException">The API refused the call.</exception>
    public Task<AISkill?> UpdateAsync(string skillId, AIUpdateSkillInput body, RequestOptions? options = null, CancellationToken cancellationToken = default)
        => _requester.CallAsync<AISkill?>("PATCH", "/api/ai/skills/" + Requester.Seg(skillId), null, body, false, "data", options, cancellationToken);
}

/// <summary><c>ai.video</c></summary>
public sealed class AiVideoResource
{
    private readonly Requester _requester;

    internal AiVideoResource(Requester requester)
    {
        _requester = requester;
    }

    /// <summary>Starts a video or GIF generation job and answers its id.</summary>
    /// <remarks>
    /// The job runs in the background; poll GET /api/ai/video/{jobId}. The duration is capped at the platform's maximum. <c>screenshot-walkthrough</c> needs a public <c>url</c> and captures it step by step. Plan limits and the platform's video settings apply.
    /// <para/>
    /// <c>POST /api/ai/video</c>
    /// </remarks>
    /// <param name="body">The body.</param>
    /// <param name="options">Per-call timeout, retries and headers.</param>
    /// <param name="cancellationToken">Cancels the call.</param>
    /// <returns>The answer.</returns>
    /// <exception cref="CrafvyException">The API refused the call.</exception>
    public Task<AiVideoCreateResponse?> CreateAsync(AiVideoCreateBody body, RequestOptions? options = null, CancellationToken cancellationToken = default)
        => _requester.CallAsync<AiVideoCreateResponse?>("POST", "/api/ai/video", null, body, false, null, options, cancellationToken);

    /// <summary>Returns a video generation job's status and, once complete, its result.</summary>
    /// <remarks>
    /// The caller's own job, or one made for an organization they belong to; any other id answers 404.
    /// <para/>
    /// <c>GET /api/ai/video/{jobId}</c>
    /// </remarks>
    /// <param name="jobId">The job's id.</param>
    /// <param name="options">Per-call timeout, retries and headers.</param>
    /// <param name="cancellationToken">Cancels the call.</param>
    /// <returns>The answer.</returns>
    /// <exception cref="CrafvyException">The API refused the call.</exception>
    public Task<AIVideoJob?> GetAsync(string jobId, RequestOptions? options = null, CancellationToken cancellationToken = default)
        => _requester.CallAsync<AIVideoJob?>("GET", "/api/ai/video/" + Requester.Seg(jobId), null, null, false, null, options, cancellationToken);
}
